// And groups predicates with the AND operator between them.
func And(predicates ...predicate.PlanItem) predicate.PlanItem {
	return predicate.PlanItem(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.PlanItem) predicate.PlanItem {
	return predicate.PlanItem(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.PlanItem) predicate.PlanItem {
	return predicate.PlanItem(sql.NotPredicates(p))
}
